// GENERATED by gen.py from ../mistralrs-quant-c/src/launch.rs -- edit the port, then regenerate.
//! Pure-Rust twins of the group-C extern "C" host launchers of mistralrs-quant
//! (libmistralrsquant.a: mmvq_gguf.cu, mmq_quantize.cu, mmq_instance_*.cu): same names, same
//! parameter lists and C ABI as the declarations in mistralrs-quant/src/gguf/ffi.rs, same grid /
//! block / shared-memory selection and host-side control flow, launching the oxide kernels on the
//! caller's stream through the CUDA driver API.
//!
//! libmistralrsquant.a is built with `--default-stream per-thread` (`__cudaLaunchKernel_ptsz`):
//! a null `stream` is the per-thread default stream, so it is launched here as
//! `CU_STREAM_PER_THREAD`.
//!
//! The oxide module is loaded once per CUDA context (the stream's context, or the current one for
//! the null stream; if no context is current, device 0's primary context, as the runtime API would)
//! and its functions are cached. The module image is the `#[cuda_module]` bundle embedded in the
//! running executable; if there is none, the PTX file named by `$MISTRALRS_QUANT_C_PTX`, else
//! `<crate>/mistralrs_quant_c.ptx`.
//!
//! Like the C launchers (`<<<>>>` without error checks), launch failures are dropped. The C
//! host-side `GGML_ASSERT`s of the MMQ launchers (fastdiv divisor 0, too many stream-k blocks)
//! print the same message and abort.
//!
//! Every launched kernel is also recorded (by its reference instance key) in `LAUNCHED`, so the
//! gate can check that each reference instance was reached through its Rust twin.
#![allow(clippy::missing_safety_doc, clippy::too_many_arguments)]
use crate::cu as sys;
use std::collections::{HashMap, HashSet};
use std::ffi::{CString, c_void};
use std::sync::{Mutex, OnceLock};

struct Module {
    module: sys::CUmodule,
    functions: HashMap<String, sys::CUfunction>,
}
// CUmodule / CUfunction are driver handles, valid from any thread of the process.
unsafe impl Send for Module {}

static MODULES: OnceLock<Mutex<HashMap<usize, Module>>> = OnceLock::new();

/// Reference instance keys launched so far (see the module docs).
pub static LAUNCHED: Mutex<Option<HashSet<String>>> = Mutex::new(None);

fn record(key: String) {
    LAUNCHED.lock().unwrap().get_or_insert_with(HashSet::new).insert(key);
}

fn module_image() -> &'static [u8] {
    crate::image::quant_c()
}

fn check(r: sys::CUresult, what: &str) {
    assert!(r == 0, "mistralrs-quant-c: {what} failed: {r:?}");
}

/// The context `stream` belongs to (the current context for the null stream).
unsafe fn stream_context(stream: sys::CUstream) -> sys::CUcontext {
    unsafe {
        check(sys::cuInit(0), "cuInit");
        let mut ctx: sys::CUcontext = std::ptr::null_mut();
        if !stream.is_null() {
            check(sys::cuStreamGetCtx(stream, &mut ctx), "cuStreamGetCtx");
            return ctx;
        }
        check(sys::cuCtxGetCurrent(&mut ctx), "cuCtxGetCurrent");
        if ctx.is_null() {
            let mut dev: sys::CUdevice = 0;
            check(sys::cuDeviceGet(&mut dev, 0), "cuDeviceGet");
            check(sys::cuDevicePrimaryCtxRetain(&mut ctx, dev), "cuDevicePrimaryCtxRetain");
            check(sys::cuCtxSetCurrent(ctx), "cuCtxSetCurrent");
        }
        ctx
    }
}

/// The oxide kernel `name` in `stream`'s context (loading the module on first use).
unsafe fn function(name: &str, stream: sys::CUstream) -> sys::CUfunction {
    unsafe {
        let ctx = stream_context(stream);
        let mut map = MODULES.get_or_init(|| Mutex::new(HashMap::new())).lock().unwrap();
        let m = map.entry(ctx as usize).or_insert_with(|| {
            let mut cur: sys::CUcontext = std::ptr::null_mut();
            check(sys::cuCtxGetCurrent(&mut cur), "cuCtxGetCurrent");
            if cur != ctx {
                check(sys::cuCtxPushCurrent_v2(ctx), "cuCtxPushCurrent");
            }
            let image = module_image();
            let mut module: sys::CUmodule = std::ptr::null_mut();
            check(sys::cuModuleLoadData(&mut module, image.as_ptr() as *const c_void), "cuModuleLoadData");
            if cur != ctx {
                let mut popped: sys::CUcontext = std::ptr::null_mut();
                check(sys::cuCtxPopCurrent_v2(&mut popped), "cuCtxPopCurrent");
            }
            Module { module, functions: HashMap::new() }
        });
        let module = m.module;
        if let Some(f) = m.functions.get(name) {
            return *f;
        }
        let mut f: sys::CUfunction = std::ptr::null_mut();
        let c = CString::new(name).unwrap();
        check(sys::cuModuleGetFunction(&mut f, module, c.as_ptr()), name);
        m.functions.insert(name.to_string(), f);
        f
    }
}

/// `CU_STREAM_PER_THREAD`: what a null stream means to a `_ptsz` launch.
const PER_THREAD: usize = 0x2;

/// One kernel argument, passed by value (its bytes).
#[derive(Clone, Copy)]
pub enum A {
    P(*const c_void),
    I(i32),
    L(i64),
}

/// Launch `name` (recorded under `key`) with the given dynamic shared memory; errors are dropped,
/// as the C `<<<>>>` drops them. `smem > 0` first raises the kernel's dynamic shared-memory limit
/// (CUDA_SET_SHARED_MEMORY_LIMIT, also unchecked).
unsafe fn launch(key: String, name: &str, grid: (u32, u32, u32), block: (u32, u32, u32), smem: u32, stream: *mut c_void, args: &[A]) {
    unsafe {
        let s = stream as sys::CUstream;
        let f = function(name, s);
        let ls = if s.is_null() { PER_THREAD as sys::CUstream } else { s };
        let mut vals: Vec<u64> = args
            .iter()
            .map(|a| match *a {
                A::P(p) => p as u64,
                A::I(v) => v as u32 as u64,
                A::L(v) => v as u64,
            })
            .collect();
        let mut ptrs: Vec<*mut c_void> = vals.iter_mut().map(|v| v as *mut u64 as *mut c_void).collect();
        record(key);
        sys::cuLaunchKernel(f, grid.0, grid.1, grid.2, block.0, block.1, block.2, smem, ls, ptrs.as_mut_ptr(), std::ptr::null_mut());
    }
}

