const TYPES: [&str; 10] = ["q4_0", "q4_1", "q5_0", "q5_1", "q8_0", "q2_k", "q3_k", "q4_k", "q5_k", "q6_k"];

fn kname(q: &str, d: &str, kind: &str, b: i32) -> String {
    format!("mmvq_gguf_{q}_{d}_{kind}_cuda{b}")
}

/// `MMVQ_LAUNCHER_PLAIN`: 2 rows per block, (8 | 4 | 2) warps for b_size (1 | <= 4 | else).
unsafe fn plain(
    q: &str, d: &str, vx: *const c_void, vy: *const c_void, dst: *mut c_void, ncols_x: i32, nrows_x: i32,
    stride_col_y: i32, stride_col_dst: i32, b_size: i32, stream: *mut c_void,
) {
    let rows_per_block: u32 = 2;
    let nblocks = (nrows_x as u32).wrapping_add(rows_per_block - 1) / rows_per_block;
    let nwarps: u32 = if b_size == 1 {
        8
    } else if b_size <= 4 {
        4
    } else {
        2
    };
    if !(1..=8).contains(&b_size) {
        return;
    }
    let n = kname(q, d, "plain", b_size);
    unsafe {
        launch(n.clone(), &n, (nblocks, 1, 1), (32, nwarps, 1), 0, stream, &[
            A::P(vx), A::P(vy), A::P(dst), A::I(ncols_x), A::I(nrows_x), A::I(stride_col_y), A::I(stride_col_dst),
        ])
    }
}

/// `MMVQ_LAUNCHER_FUSED_GLU`: rows 2 (b_size <= 1) / 1 (<= 4) / 2, warps 4 (b_size == 1) / 2.
unsafe fn fused_glu(
    q: &str, d: &str, vx_gate: *const c_void, vx_up: *const c_void, vy: *const c_void, dst: *mut c_void, ncols_x: i32,
    nrows_x: i32, stride_col_y: i32, stride_col_dst: i32, b_size: i32, activation: i32, stream: *mut c_void,
) {
    let rows_per_block: u32 = if b_size <= 1 {
        2
    } else if b_size <= 4 {
        1
    } else {
        2
    };
    let nblocks = (nrows_x as u32).wrapping_add(rows_per_block - 1) / rows_per_block;
    let nwarps: u32 = if b_size == 1 { 4 } else { 2 };
    if !(1..=8).contains(&b_size) {
        return;
    }
    let n = kname(q, d, "fused_glu", b_size);
    unsafe {
        launch(n.clone(), &n, (nblocks, 1, 1), (32, nwarps, 1), 0, stream, &[
            A::P(vx_gate), A::P(vx_up), A::P(vy), A::P(dst), A::I(ncols_x), A::I(nrows_x), A::I(stride_col_y),
            A::I(stride_col_dst), A::I(activation),
        ])
    }
}

/// `MMVQ_LAUNCHER_FUSED_QKV`: 2 rows per block; blocks packed along x when the largest matrix has
/// at least twice the rows of the smallest, else one grid row (blockIdx.y) per matrix.
unsafe fn fused_qkv(
    q: &str, d: &str, vx_q: *const c_void, vx_k: *const c_void, vx_v: *const c_void, vy: *const c_void, q_dst: *mut c_void,
    k_dst: *mut c_void, v_dst: *mut c_void, ncols_x: i32, nrows_q: i32, nrows_k: i32, nrows_v: i32, stride_col_y: i32,
    b_size: i32, stream: *mut c_void,
) {
    let rows_per_block: u32 = 2;
    let mut max_nrows = if nrows_q > nrows_k { nrows_q } else { nrows_k };
    max_nrows = if max_nrows > nrows_v { max_nrows } else { nrows_v };
    let mut min_nrows = if nrows_q < nrows_k { nrows_q } else { nrows_k };
    min_nrows = if min_nrows < nrows_v { min_nrows } else { nrows_v };
    let use_packed = max_nrows >= 2i32.wrapping_mul(min_nrows);
    let blocks = |n: i32| (n as u32).wrapping_add(rows_per_block - 1) / rows_per_block;
    let (qb, kb, vb) = (blocks(nrows_q), blocks(nrows_k), blocks(nrows_v));
    let nblocks = if use_packed { qb.wrapping_add(kb).wrapping_add(vb) } else { blocks(max_nrows) };
    let nwarps: u32 = if b_size == 1 {
        8
    } else if b_size <= 4 {
        4
    } else {
        2
    };
    if !(1..=8).contains(&b_size) {
        return;
    }
    let n = kname(q, d, "fused_qkv", b_size);
    unsafe {
        launch(n.clone(), &n, (nblocks, if use_packed { 1 } else { 3 }, 1), (32, nwarps, 1), 0, stream, &[
            A::P(vx_q), A::P(vx_k), A::P(vx_v), A::P(vy), A::P(q_dst), A::P(k_dst), A::P(v_dst), A::I(ncols_x),
            A::I(nrows_q), A::I(nrows_k), A::I(nrows_v), A::I(stride_col_y),
        ])
    }
}

macro_rules! mmvq_launchers {
    ($($plain:ident, $glu:ident, $qkv:ident, $q:literal, $d:literal;)*) => {$(
        #[unsafe(no_mangle)]
        pub unsafe extern "C" fn $plain(
            vx: *const c_void, vy: *const c_void, dst: *mut c_void, ncols_x: i32, nrows_x: i32,
            stride_col_y: i32, stride_col_dst: i32, b_size: i32, stream: *mut c_void,
        ) {
            unsafe { plain($q, $d, vx, vy, dst, ncols_x, nrows_x, stride_col_y, stride_col_dst, b_size, stream) }
        }
        #[unsafe(no_mangle)]
        pub unsafe extern "C" fn $glu(
            vx_gate: *const c_void, vx_up: *const c_void, vy: *const c_void, dst: *mut c_void, ncols_x: i32, nrows_x: i32,
            stride_col_y: i32, stride_col_dst: i32, b_size: i32, activation: i32, stream: *mut c_void,
        ) {
            unsafe { fused_glu($q, $d, vx_gate, vx_up, vy, dst, ncols_x, nrows_x, stride_col_y, stride_col_dst, b_size, activation, stream) }
        }
        #[unsafe(no_mangle)]
        pub unsafe extern "C" fn $qkv(
            vx_q: *const c_void, vx_k: *const c_void, vx_v: *const c_void, vy: *const c_void, q_dst: *mut c_void,
            k_dst: *mut c_void, v_dst: *mut c_void, ncols_x: i32, nrows_q: i32, nrows_k: i32, nrows_v: i32,
            stride_col_y: i32, b_size: i32, stream: *mut c_void,
        ) {
            unsafe { fused_qkv($q, $d, vx_q, vx_k, vx_v, vy, q_dst, k_dst, v_dst, ncols_x, nrows_q, nrows_k, nrows_v, stride_col_y, b_size, stream) }
        }
    )*};
}

