/// Quantize launchers: grid ((kx_padded + 255) / 256, num_rows), block 256.
unsafe fn mmvq_quantize(t: &str, x: *const c_void, vy: *mut c_void, kx: i32, kx_padded: i32, num_rows: i32, stream: *mut c_void) {
    let num_blocks_x = kx_padded.wrapping_add(255) / 256;
    let n = format!("mmvq_gguf_quantize_q8_1_{t}");
    unsafe {
        launch(n.clone(), &n, (num_blocks_x as u32, num_rows as u32, 1), (256, 1, 1), 0, stream, &[
            A::P(x), A::P(vy), A::I(kx), A::I(kx_padded),
        ])
    }
}
