/// `launch_mmq_quantize_glu_q8_1_f32_typed<layout>`: grid (ne1, ceil(ne0 / 512), 1), 128 threads.
unsafe fn mmq_quantize_glu(
    layout: &str, gate: *const f32, up: *const f32, ids: *const i32, vy: *mut c_void, ne00: i64, s01: i64, ne0: i64, ne1: i64,
    activation: i32, stream: *mut c_void,
) {
    let block_num_y = (ne0 + 4 * 128 - 1) / (4 * 128);
    let n = format!("quantize_mmq_q8_1_glu_f32_{layout}");
    unsafe {
        launch(n.clone(), &n, (ne1 as u32, block_num_y as u32, 1), (128, 1, 1), 0, stream, &[
            A::P(gate as *const c_void), A::P(up as *const c_void), A::P(ids as *const c_void), A::P(vy), A::L(ne00), A::L(s01),
            A::L(ne0), A::I(ne1 as i32), A::I(activation),
        ]);
    }
}

