// ================================================================================================
// mmq_instance_*.cu (+ the host helpers of mmq_common.cuh / mmq_gguf.cuh), for the sm_120a build:
// `__CUDA_ARCH_LIST__` = 1200, so ggml_cuda_highest_compiled_arch(cc) is 1200 for cc >= 1200 and
// -1 below.

const MAX_CPY_OFFSET_MTHREADS: i32 = 0x0100000;
fn is_nvidia(cc: i32) -> bool {
    cc < MAX_CPY_OFFSET_MTHREADS
}
fn highest_compiled_arch(cc: i32) -> i32 {
    if 1200 <= cc { 1200 } else { -1 }
}
fn turing_mma_available(cc: i32) -> bool {
    is_nvidia(cc) && highest_compiled_arch(cc) >= 750
}
fn volta_plus(cc: i32) -> bool {
    is_nvidia(cc) && highest_compiled_arch(cc) >= 700
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Ty {
    Q4_0,
    Q4_1,
    Q5_0,
    Q5_1,
    Q8_0,
    Q2K,
    Q3K,
    Q4K,
    Q5K,
    Q6K,
}

impl Ty {
    fn name(self) -> &'static str {
        TYPES[self as usize]
    }
    fn qk(self) -> i32 {
        match self {
            Ty::Q2K | Ty::Q3K | Ty::Q4K | Ty::Q5K | Ty::Q6K => 256,
            _ => 32,
        }
    }
    /// mmq_get_mma_tile_x_k.
    fn mma_tile_x_k(self) -> i64 {
        match self {
            Ty::Q2K => 100,
            Ty::Q3K => 84,
            _ => 76,
        }
    }
    /// mmq_get_dp4a_tile_x_sizes (qs, dm, sc).
    fn dp4a_txs(self, mmq_y: i64) -> (i64, i64, i64) {
        const K: i64 = 32;
        let q8_0 = (mmq_y * K * 2 + mmq_y, mmq_y * K * 2 / 8 + mmq_y / (8 / 2), 0);
        match self {
            Ty::Q4_0 | Ty::Q4_1 => (mmq_y * K + mmq_y, mmq_y * K / 4 + mmq_y / 4, 0),
            Ty::Q5_0 | Ty::Q8_0 => q8_0,
            Ty::Q5_1 => (mmq_y * K * 2 + mmq_y, mmq_y * K * 2 / 8 + mmq_y / (8 / 2), 0),
            Ty::Q2K => (mmq_y * K * 2 + mmq_y, mmq_y * K + mmq_y, 0),
            Ty::Q3K => (mmq_y * K * 2 + mmq_y, mmq_y, mmq_y * K / 8 + mmq_y / 8),
            Ty::Q4K => (mmq_y * K + mmq_y, mmq_y * K / 32, mmq_y * K / 8 + mmq_y / 8),
            Ty::Q5K => (mmq_y * K * 2 + mmq_y, mmq_y * K / 32 + mmq_y / 32, mmq_y * K / 8 + mmq_y / 8),
            Ty::Q6K => (mmq_y * K * 2 + mmq_y, mmq_y * K / 32 + mmq_y / 32, mmq_y * K / 8 + mmq_y / 8),
        }
    }
}

/// mmq_get_nbytes_shared<type> (size_t arithmetic).
fn nbytes_shared(t: Ty, mmq_x: i32, mmq_y: i32, cc: i32, warp_size: i32, nwarps: i32) -> u64 {
    let (qs, dm, sc) = t.dp4a_txs(mmq_y as i64);
    let nbs_ids = (mmq_x as i64 as u64).wrapping_mul(4);
    let nbs_x = if turing_mma_available(cc) {
        ((mmq_y as i64 * t.mma_tile_x_k()) as u64).wrapping_mul(4)
    } else {
        (qs as u64).wrapping_mul(4).wrapping_add((dm as u64).wrapping_mul(4)).wrapping_add((sc as u64).wrapping_mul(4))
    };
    let nbs_y = (mmq_x as i64 as u64).wrapping_mul(144);
    let n = ((nwarps.wrapping_mul(warp_size)) as i64 as u64).wrapping_mul(4);
    let pad = (nbs_y.wrapping_add(n).wrapping_sub(1)) & !(n.wrapping_sub(1));
    nbs_ids.wrapping_add(nbs_x).wrapping_add(pad)
}

/// GGML_ASSERT (host): print to stderr and abort.
fn ggml_assert(ok: bool, what: &str) {
    if !ok {
        eprintln!("GGML_ASSERT failed: {what}");
        std::process::abort();
    }
}

/// init_fastdiv_values(uint64_t d): <mp, L, d>.
fn fastdiv_values(d_64: u64) -> [u32; 3] {
    ggml_assert(d_64 != 0, "d_64 != 0");
    ggml_assert(d_64 <= u32::MAX as u64, "d_64 <= std::numeric_limits<uint32_t>::max()");
    let d = d_64 as u32;
    let mut l: u32 = 0;
    while l < 32 && (1u32 << l) < d {
        l += 1;
    }
    let mp = (((1u64 << 32) * ((1u64 << l) - d as u64)) / d as u64 + 1) as u32;
    [mp, l, d]
}

/// mmq_args.
#[derive(Clone, Copy)]
struct MmqArgs {
    x: *const c_void,
    y: *const c_void,
    ids_dst: *const i32,
    expert_bounds: *const i32,
    dst: *mut c_void,
    type_dst: i32,
    ncols_x: i64,
    nrows_x: i64,
    ncols_dst: i64,
    stride_row_x: i64,
    ncols_y: i64,
    nrows_dst: i64,
    nchannels_x: i64,
    nchannels_y: i64,
    stride_channel_x: i64,
    stride_channel_y: i64,
    stride_channel_dst: i64,
    nsamples_x: i64,
    nsamples_y: i64,
    stride_sample_x: i64,
    stride_sample_y: i64,
    stride_sample_dst: i64,
    use_stream_k: bool,
    ncols_max: i64,
}

/// CUDA_SET_SHARED_MEMORY_LIMIT: raised once per kernel instance and device, with the first size.
static RAISED: Mutex<Option<HashSet<(String, usize)>>> = Mutex::new(None);

unsafe fn set_shared_limit(name: &str, nbytes: i32, stream: *mut c_void) {
    unsafe {
        let s = stream as sys::CUstream;
        let ctx = stream_context(s) as usize;
        let mut g = RAISED.lock().unwrap();
        let set = g.get_or_insert_with(HashSet::new);
        if set.insert((name.to_string(), ctx)) {
            let f = function(name, s);
            sys::cuFuncSetAttribute(f, sys::CUfunction_attribute_enum_CU_FUNC_ATTRIBUTE_MAX_DYNAMIC_SHARED_SIZE_BYTES, nbytes);
        }
    }
}

/// instantiate_mmq_<type><mmq_x>.
unsafe fn instantiate(t: Ty, mmq_x: i32, tmp_fixup: *mut f32, a: &MmqArgs, stream: *mut c_void, cc: i32, nsm: i32, warp_size: i32) {
    let mmq_y: i32 = if volta_plus(cc) { 128 } else { 64 };
    let nwarps = 256 / warp_size;
    let nbytes = nbytes_shared(t, mmq_x, mmq_y, cc, warp_size, nwarps) as i32;
    let nty = ((a.nrows_x + mmq_y as i64 - 1) / mmq_y as i64) as i32;
    let ntx = ((a.ncols_max + mmq_x as i64 - 1) / mmq_x as i64) as i32;
    let ntzw = a.nchannels_y.wrapping_mul(a.nsamples_y) as i32;
    let block = (warp_size as u32, nwarps as u32, 1u32);
    let channel_ratio = (a.nchannels_y / a.nchannels_x) as i32;
    let sample_ratio = (a.nsamples_y / a.nsamples_x) as i32;

    let bpn = fastdiv_values((a.ncols_x / t.qk() as i64) as u64);
    let ntx_fd = fastdiv_values(ntx as i64 as u64);
    let ncy = fastdiv_values(a.nchannels_y as u64);
    let nsy = fastdiv_values(a.nsamples_y as u64);
    let cr = fastdiv_values(channel_ratio as i64 as u64);
    let sr = fastdiv_values(sample_ratio as i64 as u64);

    let names = [0, 1].map(|nc| format!("mmq_{}_x{mmq_x}_nc{nc}", t.name()));
    unsafe {
        set_shared_limit(&names[0], nbytes, stream);
        set_shared_limit(&names[1], nbytes, stream);
    }
    let fd = |v: [u32; 3]| [A::I(v[0] as i32), A::I(v[1] as i32), A::I(v[2] as i32)];
    let main_args = |fixup: *mut f32| -> Vec<A> {
        let mut v = vec![
            A::P(a.x), A::P(a.y), A::P(a.ids_dst as *const c_void), A::P(a.expert_bounds as *const c_void), A::P(a.dst),
            A::P(fixup as *const c_void),
        ];
        v.extend(fd(bpn));
        v.extend([A::I(a.nrows_x as i32), A::I(a.ncols_dst as i32), A::I(a.stride_row_x as i32), A::I(a.ncols_y as i32), A::I(a.nrows_dst as i32)]);
        v.extend(fd(cr));
        v.extend(fd(ncy));
        v.extend([A::I(a.stride_channel_x as i32), A::I(a.stride_channel_y as i32), A::I(a.stride_channel_dst as i32)]);
        v.extend(fd(sr));
        v.extend(fd(nsy));
        v.extend([A::I(a.stride_sample_x as i32), A::I(a.stride_sample_y as i32), A::I(a.stride_sample_dst as i32), A::I(a.type_dst)]);
        v.extend(fd(ntx_fd));
        v
    };
    let nc = (a.nrows_x % mmq_y as i64 != 0) as usize;
    unsafe {
        if !a.use_stream_k {
            launch(names[nc].clone(), &names[nc], (nty as u32, ntx as u32, ntzw as u32), block, nbytes as u32, stream, &main_args(std::ptr::null_mut()));
            return;
        }
        let ntiles_dst = ntx.wrapping_mul(nty).wrapping_mul(ntzw);
        let tiles_nwaves = ntiles_dst.wrapping_add(nsm - 1) / nsm;
        let eff = 100i32.wrapping_mul(ntiles_dst) / nsm.wrapping_mul(tiles_nwaves);
        let grid_sk_x: u32 = if is_nvidia(cc) && eff >= 90 { ntiles_dst as u32 } else { nsm as u32 };
        let fixup_needed = (ntiles_dst as u32) % grid_sk_x != 0;
        ggml_assert((ntiles_dst as u32).wrapping_mul(bpn[2]) < (1u32 << 30), "ntiles_dst * blocks_per_ne00_fd.z < (1 << 30)");
        launch(names[nc].clone(), &names[nc], (grid_sk_x, 1, 1), block, nbytes as u32, stream, &main_args(tmp_fixup));
        if fixup_needed {
            let fname = format!("mmq_fixup_qk{}_x{mmq_x}_nc{nc}", t.qk());
            let key = format!("mmq_fixup_{}_x{mmq_x}_nc{nc}", t.name());
            let mut v = vec![A::P(a.ids_dst as *const c_void), A::P(a.expert_bounds as *const c_void), A::P(a.dst), A::I(a.type_dst),
                             A::P(tmp_fixup as *const c_void)];
            v.extend(fd(bpn));
            v.extend([A::I(a.nrows_x as i32), A::I(a.ncols_dst as i32), A::I(a.nrows_dst as i32)]);
            v.extend(fd(ncy));
            v.push(A::I(a.stride_channel_dst as i32));
            v.extend(fd(nsy));
            v.push(A::I(a.stride_sample_dst as i32));
            v.extend(fd(ntx_fd));
            launch(key, &fname, (grid_sk_x, (mmq_y / warp_size) as u32, 1), (block.0, block.1 / 2, 1), 0, stream, &v);
        }
    }
}

/// launch_mmq_case_<type>: pick the tile width mmq_x with the fewest column tiles that fits the
/// shared-memory budget, then instantiate it.
unsafe fn launch_case(t: Ty, tmp_fixup: *mut f32, a: &MmqArgs, stream: *mut c_void, cc: i32, nsm: i32, smpbo: i64, warp_size: i32) {
    let mmq_x_max = if turing_mma_available(cc) { 128 } else { 64 };
    let mmq_y: i32 = if volta_plus(cc) { 128 } else { 64 };
    let nwarps = 256 / warp_size;
    let smpbo = smpbo as u64; // size_t parameter
    let mut mmq_x_best = 0;
    let mut ntiles_x_best = i32::MAX;
    let mut mmq_x = 8;
    while mmq_x <= mmq_x_max && ntiles_x_best > 1 {
        let granularity = if turing_mma_available(cc) && mmq_x >= 48 { 16 } else { 8 };
        if mmq_x % granularity == 0 && nbytes_shared(t, mmq_x, mmq_y, cc, warp_size, nwarps) <= smpbo {
            let ntiles_x = ((a.ncols_max + mmq_x as i64 - 1) / mmq_x as i64) as i32;
            if ntiles_x < ntiles_x_best {
                mmq_x_best = mmq_x;
                ntiles_x_best = ntiles_x;
            }
        }
        mmq_x += 8;
    }
    if mmq_x_best % 8 != 0 || !(8..=128).contains(&mmq_x_best) {
        return;
    }
    unsafe { instantiate(t, mmq_x_best, tmp_fixup, a, stream, cc, nsm, warp_size) }
}

/// launch_mmq_gguf_<type>: dense matmul, dst column stride nrows_x (stride_col_dst is ignored).
unsafe fn mmq_dense(
    t: Ty, tmp_fixup: *mut c_void, x: *const c_void, y: *const c_void, dst: *mut c_void, ncols_x: i64, nrows_x: i64, ncols_y: i64,
    stride_row_x: i64, cc: i32, nsm: i32, smpbo: i64, warp_size: i32, type_dst: i32, stream: *mut c_void,
) {
    let a = MmqArgs {
        x, y, ids_dst: std::ptr::null(), expert_bounds: std::ptr::null(), dst, type_dst, ncols_x, nrows_x, ncols_dst: ncols_y, stride_row_x,
        ncols_y, nrows_dst: nrows_x, nchannels_x: 1, nchannels_y: 1, stride_channel_x: 0, stride_channel_y: 0, stride_channel_dst: 0,
        nsamples_x: 1, nsamples_y: 1, stride_sample_x: 0, stride_sample_y: 0, stride_sample_dst: 0, use_stream_k: volta_plus(cc),
        ncols_max: ncols_y,
    };
    unsafe { launch_case(t, tmp_fixup as *mut f32, &a, stream, cc, nsm, smpbo, warp_size) }
}

/// launch_mmq_gguf_<type>_moe (DEFINE_MMQ_MOE_LAUNCHER): one channel per expert, rows of expert e
/// are y columns expert_bounds[e]..expert_bounds[e+1], written to dst column ids_dst[..]; f32 dst.
unsafe fn mmq_moe(
    t: Ty, tmp_fixup: *mut c_void, x: *const c_void, y: *const c_void, ids_dst: *const i32, expert_bounds: *const i32, dst: *mut c_void,
    ncols_x: i64, nrows_x: i64, ncols_dst: i64, stride_row_x: i64, stride_col_dst: i64, num_experts: i64, ncols_max: i64, cc: i32,
    nsm: i32, smpbo: i64, warp_size: i32, stream: *mut c_void,
) {
    // dst column stride = stride_col_dst, as DEFINE_MMQ_MOE_LAUNCHER passes it (nrows_dst); the dense launcher
    // ignores its stride_col_dst, the MoE one does not (gate/up packed into one buffer use 2 * nrows).
    let a = MmqArgs {
        x, y, ids_dst, expert_bounds, dst, type_dst: 0, ncols_x, nrows_x, ncols_dst, stride_row_x, ncols_y: ncols_dst, nrows_dst: stride_col_dst,
        nchannels_x: num_experts, nchannels_y: num_experts, stride_channel_x: nrows_x.wrapping_mul(stride_row_x), stride_channel_y: 0,
        stride_channel_dst: 0, nsamples_x: 1, nsamples_y: 1, stride_sample_x: 0, stride_sample_y: 0, stride_sample_dst: 0,
        use_stream_k: volta_plus(cc), ncols_max,
    };
    unsafe { launch_case(t, tmp_fixup as *mut f32, &a, stream, cc, nsm, smpbo, warp_size) }
}

macro_rules! mmq_launchers {
    ($($dense:ident, $moe:ident, $t:expr;)*) => {$(
        /// Same signature and launch logic as the mistralrs-quant C launcher of this name.
        #[unsafe(no_mangle)]
        pub unsafe extern "C" fn $dense(
            tmp_fixup: *mut c_void, x: *const c_void, y: *const c_void, dst: *mut c_void, ncols_x: i64, nrows_x: i64, ncols_y: i64,
            stride_row_x: i64, _stride_col_dst: i64, cc: i32, nsm: i32, smpbo: i64, warp_size: i32, type_dst: i32, stream: *mut c_void,
        ) {
            unsafe { mmq_dense($t, tmp_fixup, x, y, dst, ncols_x, nrows_x, ncols_y, stride_row_x, cc, nsm, smpbo, warp_size, type_dst, stream) }
        }
        /// Same signature and launch logic as the mistralrs-quant C launcher of this name.
        #[unsafe(no_mangle)]
        pub unsafe extern "C" fn $moe(
            tmp_fixup: *mut c_void, x: *const c_void, y: *const c_void, ids_dst: *const i32, expert_bounds: *const i32, dst: *mut c_void,
            ncols_x: i64, nrows_x: i64, ncols_dst: i64, stride_row_x: i64, stride_col_dst: i64, num_experts: i64, ncols_max: i64,
            cc: i32, nsm: i32, smpbo: i64, warp_size: i32, stream: *mut c_void,
        ) {
            unsafe {
                mmq_moe($t, tmp_fixup, x, y, ids_dst, expert_bounds, dst, ncols_x, nrows_x, ncols_dst, stride_row_x, stride_col_dst, num_experts, ncols_max,
                        cc, nsm, smpbo, warp_size, stream)
            }
        }
    )*};
}
mmq_launchers! {
    launch_mmq_gguf_q4_0, launch_mmq_gguf_q4_0_moe, Ty::Q4_0;
    launch_mmq_gguf_q4_1, launch_mmq_gguf_q4_1_moe, Ty::Q4_1;
    launch_mmq_gguf_q5_0, launch_mmq_gguf_q5_0_moe, Ty::Q5_0;
    launch_mmq_gguf_q5_1, launch_mmq_gguf_q5_1_moe, Ty::Q5_1;
    launch_mmq_gguf_q8_0, launch_mmq_gguf_q8_0_moe, Ty::Q8_0;
    launch_mmq_gguf_q2_k, launch_mmq_gguf_q2_k_moe, Ty::Q2K;
    launch_mmq_gguf_q3_k, launch_mmq_gguf_q3_k_moe, Ty::Q3K;
    launch_mmq_gguf_q4_k, launch_mmq_gguf_q4_k_moe, Ty::Q4K;
    launch_mmq_gguf_q5_k, launch_mmq_gguf_q5_k_moe, Ty::Q5K;
    launch_mmq_gguf_q6_k, launch_mmq_gguf_q6_k_moe, Ty::Q6K;
}

/// For the gate: the (mmq_x, stream-k grid) a launcher call picks, so tmp_fixup slots can be
/// mapped to their output tile. `qk` selects the type's shared-memory sizes via its name.
pub fn plan(tname: &str, ncols_max: i64, nrows_x: i64, nchannels: i64, cc: i32, nsm: i32, smpbo: i64) -> Option<(i32, u32)> {
    let t = [Ty::Q4_0, Ty::Q4_1, Ty::Q5_0, Ty::Q5_1, Ty::Q8_0, Ty::Q2K, Ty::Q3K, Ty::Q4K, Ty::Q5K, Ty::Q6K][TYPES.iter().position(|n| *n == tname)?];
    let (mmq_x_max, mmq_y, nwarps) = (if turing_mma_available(cc) { 128 } else { 64 }, 128, 8);
    let (mut best, mut nbest) = (0, i32::MAX);
    let mut x = 8;
    while x <= mmq_x_max && nbest > 1 {
        let gran = if turing_mma_available(cc) && x >= 48 { 16 } else { 8 };
        if x % gran == 0 && nbytes_shared(t, x, mmq_y, cc, 32, nwarps) <= smpbo as u64 {
            let n = ((ncols_max + x as i64 - 1) / x as i64) as i32;
            if n < nbest {
                best = x;
                nbest = n;
            }
        }
        x += 8;
    }
    if best == 0 {
        return None;
    }
    let nty = ((nrows_x + 127) / 128) as i32;
    let ntx = ((ncols_max + best as i64 - 1) / best as i64) as i32;
    let ntiles = ntx * nty * nchannels as i32;
    let waves = (ntiles + nsm - 1) / nsm;
    let eff = 100 * ntiles / (nsm * waves);
    Some((best, if eff >= 90 { ntiles as u32 } else { nsm as u32 }))
}
